import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        if (line.isEmpty()) return;
        int capacity;
        try {
            capacity = Integer.parseInt(line);
        } catch (NumberFormatException e) {
            return;
        }
        int[] queue = new int[capacity];
        int front = 0, rear = 0, size = 0;

        StringBuilder output = new StringBuilder();
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            if (line.equalsIgnoreCase("exit")) {
                break;
            } else if (line.toLowerCase().startsWith("enqueue")) {
                String[] parts = line.split("\\s+");
                if (parts.length < 2) continue;
                int val;
                try {
                    val = Integer.parseInt(parts[1]);
                } catch (NumberFormatException e) {
                    continue;
                }
                if (size < capacity) {
                    queue[rear] = val;
                    rear = (rear + 1) % capacity;
                    size++;
                }
            } else if (line.equalsIgnoreCase("dequeue")) {
                if (size > 0) {
                    front = (front + 1) % capacity;
                    size--;
                }
            } else if (line.equalsIgnoreCase("display")) {
                for (int i = 0; i < size; i++) {
                    int idx = (front + i) % capacity;
                    output.append(queue[idx]);
                    if (i < size - 1) output.append(' ');
                }
                output.append('\n');
            }
        }
        System.out.print(output.toString());
    }
}
